module Prob_8_24 # (parameter dp_width = 5) (  output 	[2*dp_width - 1: 0] 	Product,  output							Ready,  input 	[dp_width - 1: 0] 		Multiplicand, Multiplier,  input 							Start, clock, reset_b);  wire Load_regs, Decr_P, Add_regs, Shift_regs, Zero, Q0;  Controller M0 (    Ready, Load_regs, Decr_P, Add_regs, Shift_regs, Start, Zero, Q0,     clock, reset_b);Datapath M1(Product, Q0, Zero,Multiplicand, Multiplier,  Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);	endmodulemodule Controller (  output Ready,  output reg Load_regs, Decr_P, Add_regs, Shift_regs,     input Start, Zero, Q0, clock, reset_b);  parameter		S_idle =	3'b001, 		// one-hot code        				S_add = 	3'b010, 		       				S_shift = 	3'b100;  reg	[2: 0]		state, next_state;		// sized for one-hot  assign			Ready = (state == S_idle);	    always @ (posedge clock, negedge reset_b)    if (~reset_b) state <= S_idle; else state <= next_state;  always @ (state, Start, Q0, Zero) begin    next_state = S_idle;    Load_regs = 0;    Decr_P = 0;    Add_regs = 0;    Shift_regs = 0;    case (state)      S_idle:	if (Start) begin next_state = S_add; Load_regs = 1; end      S_add:	begin next_state = S_shift; Decr_P = 1; if (Q0) Add_regs = 1; end      S_shift:	begin 		  Shift_regs = 1; 		  if (Zero) next_state = S_idle; 		  else next_state = S_add;        end      default:	next_state = S_idle;    endcase  endendmodule
module Datapath #(parameter dp_width = 5, BC_size = 3) (  output [2*dp_width - 1: 0] Product, output Q0, output Zero,  input [dp_width - 1: 0] Multiplicand, Multiplier,  input Start, Load_regs, Decr_P, Add_regs, Shift_regs, clock, reset_b);// Default configuration: 5-bit datapath  reg	[dp_width - 1: 0]		A, B, Q;				// Sized for datapath  reg 				C;  reg	[BC_size - 1: 0]		P;				// Bit counter    assign Q0 = Q[0];	  assign	Zero = (P == 0);			// Counter is zero  assign Product = {C, A, Q};  always @ (posedge clock, negedge reset_b)     if (reset_b == 0) begin			// Added to this solution, but      P <= dp_width;					// not really necessary since Load_regs      B <= 0;							// initializes the datapath      C <= 0;      A <= 0;      Q <= 0;    end     else begin    if (Load_regs) begin      P <= dp_width;      A <= 0;      C <= 0;      B <= Multiplicand;      Q <= Multiplier;    end    if (Add_regs) {C, A} <= A + B;    if (Shift_regs) {C, A, Q} <= {C, A, Q} >> 1;    if (Decr_P) P <= P -1;  endendmodule module t_Prob_8_24;  parameter					dp_width = 5;			// Width of datapath  wire	[2 * dp_width - 1: 0] 	Product;  wire							Ready;  reg 	[dp_width - 1: 0] 		Multiplicand, Multiplier;   reg 							Start, clock, reset_b;  integer						Exp_Value;  reg							Error;  Prob_8_24 M0(Product, Ready, Multiplicand, Multiplier, Start, clock, reset_b);  initial #115000 $finish;  initial begin clock = 0; #5 forever #5 clock = ~clock; end  initial fork    reset_b = 1;    #2 reset_b = 0;    #3 reset_b = 1;  join  always @ (negedge Start) begin    Exp_Value = Multiplier * Multiplicand;    //Exp_Value = Multiplier * Multiplicand +1;	// Inject error to confirm detection  end  always @ (posedge Ready) begin    # 1 Error <= (Exp_Value ^ Product) ;  end  initial begin    #5 Multiplicand = 0;    Multiplier = 0;        repeat (32) #10 begin        Start = 1;        #10 Start = 0;        repeat (32) begin          Start = 1;          #10 Start = 0;                    #100 Multiplicand = Multiplicand + 1;        end      Multiplier = Multiplier + 1;    end  endendmodule